    for(const entry of result.entries){const card=document.createElement('article');card.className='sign-card reference-card';const status=recognitionStatus(entry,api.getEntries(),api.getModels());const badge=document.createElement('span');badge.className='badge';badge.textContent=entry.clipBlob?(entry.clipBlob.type.startsWith('image/')?'MY REFERENCE IMAGE':'MY LESSON VIDEO'):entry.media?'SOURCE VIDEO':entry.kind==='alphabet'?'ASL LETTER':'REFERENCE LESSON';const title=document.createElement('h3');title.textContent=entry.label;const source=document.createElement('p');source.textContent=entry.source;const available=document.createElement('div');available.className='caption';available.textContent=status.label;const actions=document.createElement('div');actions.className='actions';const learn=document.createElement('button');learn.className='text-button';learn.textContent='Show / practice ↗';learn.onclick=()=>selectEntry(entry);const reference=document.createElement('a');reference.href=entry.referenceUrl;reference.target='_blank';reference.rel='noopener';reference.textContent='Source ↗';actions.append(learn,reference);card.append(badge,title,source,available,actions);$('catalog-results').append(card);}
