  function videoControls(video){video.playbackRate=Number($('lesson-video-speed').value);video.loop=$('lesson-video-loop').checked;video.onended=()=>{if(watching&&$('lesson-video-advance').checked&&!video.loop&&current<plan.steps.length-1){current++;renderPlan();}};}
