  function manageReferences(){const box=$('saved-reference-list');box.replaceChildren();for(const e of imported.filter(e=>e.language===$('lesson-language').value)){const row=document.createElement('div');row.className='saved-reference-row';const name=document.createElement('span');name.textContent=e.label+' · '+e.source;const watch=document.createElement('button');watch.className='text-button';watch.textContent='Practice';watch.onclick=()=>selectEntry(e);const remove=document.createElement('button');remove.className='text-button';remove.textContent='Remove';remove.onclick=async()=>{if(await api.confirmAction('Remove saved lesson?','Remove this reference link from your device? Bundled lessons and personal clips stay available.')){try{const next=imported.filter(x=>x.language!==e.language||x.id!==e.id);await saveReferences(next);imported=next;manageReferences();rebuildSavedPlan();}catch{api.toast('Could not remove the lesson. Retry.');}}};row.append(name,watch,remove);box.append(row);}if(!box.children.length){const p=document.createElement('p');p.className='caption';p.textContent='No saved links for the selected language.';box.append(p);}}
  $('save-reference').onclick=async()=>{try{const label=$('reference-label').value.trim(),source=$('reference-source').value.trim(),referenceUrl=$('reference-page').value.trim(),language=$('lesson-language').value;if(!$('reference-verified').checked)throw Error('Check the lesson’s language and meaning before saving.');const media=parseVideoLink($('reference-video').value);const alphabet=$('reference-letter').checked;if(alphabet&&!/^[A-Za-z]$/.test(label))throw Error('For a Latin manual letter, use one label from A to Z. Other writing systems can be saved as regular lessons.');const entry={id:'saved-'+crypto.randomUUID(),language,label,aliases:[],source,referenceUrl,kind:alphabet?'alphabet':'reference',category:alphabet?'My manual letters':'My saved lessons',media,instruction:$('reference-notes').value.trim()};validateReferenceCatalog({schemaVersion:1,entries:[entry]});const next=[...imported,entry];validateReferenceCatalog({schemaVersion:1,entries:next});await saveReferences(next);imported=next;$('reference-verified').checked=false;$('reference-video').value='';$('reference-letter').checked=false;rebuildSavedPlan();manageReferences();api.toast('Lesson saved. Rebuild or watch your vocabulary practice sequence.');}catch(error){api.toast('Lesson could not be saved: '+error.message);}};
  $('manage-references').onclick=()=>{$('saved-reference-list').hidden=!$('saved-reference-list').hidden;manageReferences();};
  $('export-references').onclick=()=>api.download('signvoice-lesson-links.json',JSON.stringify({schemaVersion:1,entries:imported},null,2));
  $('lesson-watch').onclick=()=>{if(!plan?.steps.length)return;watching=!watching;clearAdvance();if(watching)current=0;renderPlan();};
  $('lesson-video-speed').onchange=()=>{const video=$('lesson-demonstration').querySelector('video');if(video)video.playbackRate=Number($('lesson-video-speed').value);};
  $('lesson-video-loop').onchange=()=>{const video=$('lesson-demonstration').querySelector('video');if(video)video.loop=$('lesson-video-loop').checked;};
  window.addEventListener('sv-clips-changed',reloadClips);
  $('build-lesson').onclick=build;$('lesson-text').onkeydown=e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();build();}};
  $('lesson-language').onchange=()=>{avatar.invalidate();watching=false;releaseMedia();renderGlobalResources($('lesson-language').value,'lesson-global-resources');clearAdvance();$('fingerspell-fallback').disabled=false;if(plan){plan=null;$('lesson-queue').replaceChildren();$('lesson-summary').textContent='Language changed. Select Show me the signs to rebuild your practice sequence.';renderStep();$('practice-status').textContent='Build a sequence for the selected language.';}manageReferences();api.setLanguage($('lesson-language').value);};
