  $('practice-camera').onclick=()=>{api.setLanguage(plan?.language||$('lesson-language').value);api.startCamera();};$('practice-stop-camera').onclick=()=>{clearAdvance();api.stopCamera();previewCtx.clearRect(0,0,preview.width,preview.height);};
